model.example:
// A sword on its own, hanging still in the air.
const model = kcds.players.Items.model('longSwordDuel');
if (model.endsWith('.cgf')) {
  const spot = new kcds.math.Vector3(1650, 2151, 37);
  kcds.world.Prop.spawn(model, spot, undefined, undefined, 'none');
}

model.exampleCs:
// A sword on its own, hanging still in the air.
var model = Items.Model("longSwordDuel");
if (model.EndsWith(".cgf"))
{
    var spot = new Vector3(1650, 2151, 37);
    Prop.Spawn(model, spot, null, null, "none");
}

register.example:
const { Items, Inventory } = kcds.players;

const sealedLetter = Items.register('myres:sealed_letter', {
  name: 'Sealed letter',
  description: 'A letter with the seal of the burgrave.',
  visual: 'crime_letterOfRecognition',
  weight: 0.1,
  usable: true,
  useLabel: 'Break the seal',
});
Inventory.add(player, { item: sealedLetter, amount: 1 });

kcds.core.Events.on('playerCustomItemUse', (reader, row, revision) => {
  kcds.core.Chat.sendToPlayer(reader, 'The seal breaks.');
});

register.exampleCs:
var sealedLetter = Items.Register("myres:sealed_letter", new { name = "Sealed letter", description = "A letter with the seal of the burgrave.", visual = "crime_letterOfRecognition", weight = 0.1, usable = true, useLabel = "Break the seal" });
Inventory.Add(player, new { item = sealedLetter, amount = 1 });

Events.On("playerCustomItemUse", (Player reader, JsValue row, JsValue revision) =>
{
    Chat.SendToPlayer(reader, "The seal breaks.");
});

